#include <stdio.h>

/* Los datos de un envío */
struct Envio {
    const char *destino;
    int pesoKg;
    int enRuta;
};

/* El «método»: el primer parámetro es el envío, escrito a la vista */
void despachar(struct Envio *self) {
    self->enRuta = 1;
}

int main(void) {
    struct Envio a = {"Rosario", 120, 0};
    struct Envio b = {"Mendoza", 80, 0};
    despachar(&a);
    printf("%s: %d\n", a.destino, a.enRuta);
    printf("%s: %d\n", b.destino, b.enRuta);
    return 0;
}

