// Trampa 3: una función común dentro de un método
class Reparto {
  constructor(envios) {
    this.envios = envios;
    this.contados = 0;
  }
  contarMal() {
    this.envios.forEach(function () {
      this.contados++; // acá this ya no es el reparto
    });
  }
  contarBien() {
    this.envios.forEach(() => {
      this.contados++; // la flecha conserva el this del método
    });
  }
}
const r = new Reparto([1, 2, 3]);
try {
  r.contarMal();
} catch (err) {
  console.log("3)", err.constructor.name, "-", err.message);
}
r.contarBien();
console.log("contados:", r.contados);

