class Envio {
  static #proximo = 1; // un solo contador, de la clase y no de cada envío
  #pesoKg;
  #estado = "pendiente";

  constructor(destino, pesoKg) {
    this.id = Envio.#proximo++;
    this.destino = destino;
    this.pesoKg = pesoKg; // pasa por el setter: la regla vive en un solo lugar
  }

  // Método estático: se llama sobre la clase, no sobre un envío
  static desdeRemito(texto) {
    const [destino, peso] = texto.split(";");
    return new Envio(destino.trim(), Number(peso));
  }

  get pesoKg() {
    return this.#pesoKg;
  }
  set pesoKg(valor) {
    if (!(valor > 0)) throw new RangeError(`Peso inválido: ${valor}`);
    this.#pesoKg = valor;
  }

  get estado() {
    return this.#estado;
  }
  despachar() {
    if (this.#estado !== "pendiente") throw new Error(`Envío ${this.id}: no se despacha desde «${this.#estado}»`);
    this.#estado = "en ruta";
  }
  entregar() {
    if (this.#estado !== "en ruta") throw new Error(`Envío ${this.id}: no se entrega desde «${this.#estado}»`);
    this.#estado = "entregado";
  }
}

