class Envio {
  static #proximo = 1;
  #estado = "pendiente";
  constructor(destino, pesoKg) {
    if (!(pesoKg > 0)) throw new RangeError(`Peso inválido: ${pesoKg}`);
    this.id = Envio.#proximo++;
    this.destino = destino;
    this.pesoKg = pesoKg;
  }
  get estado() { return this.#estado; }
  despachar() {
    if (this.#estado !== "pendiente") throw new Error(`Envío ${this.id}: ya salió`);
    this.#estado = "en ruta";
  }
  entregar() {
    if (this.#estado !== "en ruta") throw new Error(`Envío ${this.id}: no está en ruta`);
    this.#estado = "entregado";
  }
}

class Camion {
  #cargaKg = 0;
  #envios = [];

  constructor(patente, capacidadKg) {
    this.patente = patente;
    this.capacidadKg = capacidadKg;
  }

  get disponibleKg() { return this.capacidadKg - this.#cargaKg; }
  get envios() { return [...this.#envios]; } // una copia: desde afuera no se puede meter nada

  cargar(envio) {
    if (envio.pesoKg > this.disponibleKg) {
      throw new Error(`${this.patente}: no entran ${envio.pesoKg} kg (quedan ${this.disponibleKg})`);
    }
    this.#envios.push(envio);
    this.#cargaKg += envio.pesoKg;
  }

  salir() { this.#envios.forEach((e) => e.despachar()); }
  entregarTodo() { this.#envios.forEach((e) => e.entregar()); }
  resumen() {
    const lista = this.#envios.map((e) => `#${e.id} ${e.destino} (${e.estado})`).join(", ");
    return `${this.patente}: ${this.#cargaKg}/${this.capacidadKg} kg · ${lista || "vacío"}`;
  }
}

